class Solution:
    def canMakePaliQueries(self, s: str, queries: list[list[int]]) -> list[bool]:
        n = len(s)
        prefix = [0] * (n + 1)
        for i, c in enumerate(s):
            prefix[i + 1] = prefix[i] ^ (1 << (ord(c) - ord('a')))

        res = []
        for left, right, k in queries:
            mask = prefix[right + 1] ^ prefix[left]
            odd_cnt = bin(mask).count('1')
            res.append(odd_cnt // 2 <= k)
        return res

class Solution {
public:
    vector<bool> canMakePaliQueries(string s, vector<vector<int>>& queries) {
        int n = s.size();
        vector<int> prefix(n + 1, 0);
        for (int i = 0; i < n; ++i) {
            prefix[i + 1] = prefix[i] ^ (1 << (s[i] - 'a'));
        }
        vector<bool> res;
        res.reserve(queries.size());
        for (const auto& q : queries) {
            int mask = prefix[q[1] + 1] ^ prefix[q[0]];
            int odd_cnt = __builtin_popcount(mask);
            res.push_back(odd_cnt / 2 <= q[2]);
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public List<Boolean> canMakePaliQueries(String s, int[][] queries) {
        int n = s.length();
        int[] prefix = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] ^ (1 << (s.charAt(i) - 'a'));
        }
        List<Boolean> res = new ArrayList<>(queries.length);
        for (int[] q : queries) {
            int mask = prefix[q[1] + 1] ^ prefix[q[0]];
            int oddCnt = Integer.bitCount(mask);
            res.add(oddCnt / 2 <= q[2]);
        }
        return res;
    }
}

var canMakePaliQueries = function(s, queries) {
    const n = s.length;
    const prefix = new Array(n + 1).fill(0);
    const code = (c) => c.charCodeAt(0) - 97;
    for (let i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] ^ (1 << code(s[i]));
    }

    const countBits = (n) => {
        let cnt = 0;
        while (n > 0) {
            cnt += n & 1;
            n >>= 1;
        }
        return cnt;
    };

    return queries.map(([l, r, k]) => {
        const mask = prefix[r + 1] ^ prefix[l];
        const oddCnt = countBits(mask);
        return Math.floor(oddCnt / 2) <= k;
    });
};
